{
  "claims": [
    {
      "claim_text": "SQLite has three checkpoint subtypes: PASSIVE, FULL and RESTART.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 5 explicitly states there are three subtypes: PASSIVE, FULL, and RESTART.",
      "citations": [
        {
          "index": 5,
          "quote": "There are three subtypes of checkpoints that vary in their aggressiveness: PASSIVE, FULL, and RESTART."
        }
      ]
    },
    {
      "claim_text": "Every checkpoint started with sqlite3_wal_checkpoint() or by the automatic mechanism is PASSIVE.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 5 directly states this.",
      "citations": [
        {
          "index": 5,
          "quote": "All checkpoints initiated by sqlite3_wal_checkpoint() and by the automatic checkpoint mechanism are PASSIVE."
        }
      ]
    },
    {
      "claim_text": "Calling sqlite3_wal_checkpoint_v2() always produces a FULL or RESTART checkpoint.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 5 says FULL and RESTART checkpoints can only be initiated by sqlite3_wal_checkpoint_v2(), but it does not say that every call to sqlite3_wal_checkpoint_v2() produces a FULL or RESTART checkpoint. In fact, the default checkpoint style is PASSIVE, and sqlite3_wal_checkpoint_v2() can presumably be used with PASSIVE as well. The claim overstates the relationship.",
      "citations": [
        {
          "index": 5,
          "quote": "The default checkpoint style is PASSIVE, which does as much work as it can without interfering with other database connections, and which might not run to completion if there are concurrent readers or writers."
        },
        {
          "index": 5,
          "quote": "FULL and RESTART checkpoints try harder to run the checkpoint to completion and can only be initiated by a call to sqlite3_wal_checkpoint_v2()."
        }
      ]
    },
    {
      "claim_text": "A PASSIVE checkpoint is guaranteed to run to completion as long as no other connection is writing.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 5 says a PASSIVE checkpoint might not run to completion if there are concurrent readers or writers. Passage 7 says a checkpoint can only run to completion if there are no other database connections using the WAL file, and a read transaction can prevent completion. Thus, absence of writers alone does not guarantee completion; readers can also block it.",
      "citations": [
        {
          "index": 5,
          "quote": "The default checkpoint style is PASSIVE, which does as much work as it can without interfering with other database connections, and which might not run to completion if there are concurrent readers or writers."
        },
        {
          "index": 7,
          "quote": "A checkpoint is only able to run to completion, and reset the WAL file, if there are no other database connections using the WAL file."
        }
      ]
    },
    {
      "claim_text": "Because a checkpoint can only reset the WAL when no other connection is using it, a checkpoint will always reset the WAL whenever the WAL is unused.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passages state that a checkpoint can only reset the WAL if no other connection is using it, but they do not state that a checkpoint will always reset the WAL whenever it is unused. Other factors (e.g., checkpoint type, whether it runs to completion) may affect resetting. The claim is not entailed.",
      "citations": []
    },
    {
      "claim_text": "The automatic checkpoint is implemented on top of sqlite3_wal_hook().",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 4 explicitly states this.",
      "citations": [
        {
          "index": 4,
          "quote": "The automatic checkpoint mechanism is implemented as a simple wrapper around sqlite3_wal_hook()."
        }
      ]
    },
    {
      "claim_text": "The automatic checkpoint runs in the same thread as the COMMIT that pushes the WAL over its size limit.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 3 states that by default the checkpoint is run automatically by the same thread that does the COMMIT that pushes the WAL over its size limit.",
      "citations": [
        {
          "index": 3,
          "quote": "By default, the checkpoint will be run automatically by the same thread that does the COMMIT that pushes the WAL over its size limit."
        }
      ]
    },
    {
      "claim_text": "Because of this, long-running readers never delay the automatic checkpoint.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 2 states that a long-running read transaction can prevent a checkpointer from making progress. Passage 7 explains that if another connection has a read transaction open, the checkpoint cannot reset the WAL and cannot run to completion. This applies to automatic checkpoints as well, since they are PASSIVE. Thus long-running readers can delay automatic checkpoints.",
      "citations": [
        {
          "index": 2,
          "quote": "Thus a long-running read transaction can prevent a checkpointer from making progress."
        },
        {
          "index": 7,
          "quote": "If another connection has a read transaction open, then the checkpoint cannot reset the WAL file because doing so might delete content out from under the reader."
        }
      ]
    }
  ]
}
